#include <linux/tracepoint.h>
#include <linux/ring_buffer.h>

void handle_syscall_exit(void *data, struct pt_regs *regs, long ret) {
    int syscall_num = (int)regs->ax;
    struct trace_array *tr = data;
    struct trace_event_file *file = NULL;
    struct ring_buffer *buffer = tr->trace_buffer.buffer;
    struct ring_buffer_event *event;
    struct syscall_exit_event *entry;

    if (syscall_num < 0 || syscall_num >= __NR_syscalls) {
        return;
    }

    file = find_event_file(tr, syscalls_id, syscall_num);
    if (!file || !file->enabled) {
        return;
    }

    event = ring_buffer_reserve(buffer, sizeof(*entry));
    if (!event) {
        return;
    }

    entry = ring_buffer_event_data(event);
    entry->syscall_num = syscall_num;
    entry->ret = ret;

    ring_buffer_commit(event);
}
